package workcmd

func resourceWriteCommands() []Command {
	command := func(name, summary string, fields []InputField, result string) Command {
		return Command{Name: name, Version: 1, CredentialPurpose: "worker", Summary: summary, Scope: "current authorized scope and this role's exact bound connector", InputFields: fields, Result: result}
	}
	receipt := "Actual external IDs/revision and partial receipt; unknown writes are retained without automatic resend. Written does not mean saved snapshot, delivered, read or accepted."
	return []Command{
		command("project.directory.select", "Save the actual initiating human’s explicit new parent during project establishment; preserve old uncertain creates and relocate the same known home object.", []InputField{{"key", "Stable selection key."}, {"project_id", "Current establishing project."}, {"expected_project_revision", "Exact project revision."}, {"expected_directory_generation", "Current directory generation, initially zero."}, {"document_container", "Existing folder/Wiki parent URL explicitly present in this run’s own human message."}, {"source_message_id", "Current admitted actual creator message; agent cannot claim another owner."}}, "selection_saved with authoritative directory generation; not a completed move. Old-generation effects are fenced; unknown creation without an ID blocks any new create."),
		command("resource.comments.read", "Read and persist an actual document comment/reply page after missed notifications; preserve original IDs, quote and solved state without claiming business resolution.", []InputField{{"key", "Stable observation key; new key reads new source facts."}, {"resource_id", "Same-scope registered supported document/spreadsheet."}, {"comment_id", "Optional actual comment ID to read a page of its replies."}, {"page_token", "Continuation for the same comment list or reply thread."}, {"page_size", "0..50, default20."}}, "Durable observation_ref, observed_at and page cursors; each comment also preserves its own remaining-reply cursor. Quote/anchors may no longer map to current text; no realtime/all-comments or human-acceptance claim."),
		command("resource.write.observe", "Read the actual object returned by a prior write without retrying it; current state never proves an unknown call succeeded.", []InputField{{"key", "Stable read observation key; use a new key for a new observation."}, {"operation_id", "This role’s original resource write operation."}, {"page_token", "Docx continuation from the same inspection revision."}, {"document_revision", "Required previous requested_revision when continuing a document observation."}, {"page_size", "0..50, default20."}}, "Original write state and independently persisted document/sheet observation. Original unknown is retained; creation without an actual returned ID requires an explicit human-selected existing resource, never title matching or recreation."),
		command("resource.list", "List registered materials and explicitly selected parent directories without loading their content.", []InputField{{"limit", "Page size1..100, default20."}, {"after", "Prior next_after."}, {"directories_only", "Only registered creation parents."}}, "items with canonical identities, purpose and revisions; next_after."),
		command("resource.document.create", "Create one Docx in an explicitly registered existing Drive folder or Wiki parent; never create a Wiki space.", []InputField{{"key", "Stable idempotency key; do not change it to retry an unknown creation."}, {"parent_resource_id", "Same-scope registered parent directory."}, {"expected_parent_revision", "Exact parent resource revision."}, {"title", "Document title."}, {"purpose", "Why this work creates it."}, {"collection_id", "Explicit material collection."}}, receipt),
		command("resource.document.inspect", "Inspect actual Docx block identities, full-block hashes and bounded text-run previews at a frozen revision.", []InputField{{"resource_id", "Registered Docx resource."}, {"document_revision", "Optional positive historical revision; zero freezes the current metadata revision."}, {"block_id", "Optional exact block; required with text_run_index."}, {"page_token", "Continuation only for the same document revision."}, {"page_size", "1..50 blocks, default20."}, {"text_run_index", "Optional zero-based actual text run selected from block inspection."}, {"offset", "Text-run character offset."}, {"limit", "Text-run characters1..8000, default4000."}}, "observed_revision, requested_revision, block/run identities, full-block SHA256, has_more/next_page_token; a page never proves the whole document was read."),
		command("resource.document.append", "Append explicit paragraphs to a selected Docx parent block after checking the observed current revision; API revision is not a CAS guarantee.", []InputField{{"key", "Stable write key."}, {"resource_id", "Registered Docx resource."}, {"expected_resource_revision", "Exact registration revision."}, {"observed_document_revision", "Actual current revision returned by inspect."}, {"parent_block_id", "Exact existing parent block."}, {"index", "Explicit insertion position; omitted or -1 appends."}, {"paragraphs", "1..50 new text paragraphs."}}, receipt),
		command("resource.document.update", "Replace only named text runs while preserving other runs/styles; preflight verifies full-block hashes, without claiming platform CAS.", []InputField{{"key", "Stable write key."}, {"resource_id", "Registered Docx resource."}, {"expected_resource_revision", "Exact registration revision."}, {"observed_document_revision", "Actual current inspect revision."}, {"edits", "1..50 {block_id,text_run_index,expected_block_sha256,text}; use identities/hash returned by inspect."}}, receipt),
		command("resource.sheet.read", "Read an explicit bounded spreadsheet range with formula representation and original revision evidence.", []InputField{{"resource_id", "Registered spreadsheet."}, {"sheet_id", "Exact tab identity."}, {"range", "Explicit A1 rectangle, optionally prefixed by the matching sheet ID."}}, "values with original formula/rich objects, raw revisions and data_sha256 for the exact range."),
		command("resource.sheet.write", "Write only an explicit rectangle after matching its observed data hash; no revision CAS is offered by this API.", []InputField{{"key", "Stable write key."}, {"resource_id", "Registered spreadsheet."}, {"expected_resource_revision", "Exact registration revision."}, {"sheet_id", "Exact tab identity."}, {"range", "Explicit bounded rectangle; value dimensions must match."}, {"expected_data_sha256", "Actual exact-range hash from resource.sheet.read."}, {"values", "Exact matrix of platform cell values; formulas use {type:formula,text:=...}, not inferred/coerced values."}}, receipt),
	}
}
